import{_ as a,l as S,o as i,b as d,q as n,d as e,f as t,m as l}from"./chunks/framework.Tf23FRXt.js";const T=JSON.parse('{"title":"神兵要塞帝国南方堡","description":"","frontmatter":{},"headers":[{"level":2,"title":"进场 ~ BOSS 1","slug":"进场-boss-1","link":"#进场-boss-1","children":[{"level":3,"title":"BOSS 1 魔导死神改","slug":"boss-1-魔导死神改","link":"#boss-1-魔导死神改","children":[]}]},{"level":2,"title":"BOSS 1 ~ BOSS 2","slug":"boss-1-boss-2","link":"#boss-1-boss-2","children":[{"level":3,"title":"BOSS 2 魔导先锋强袭型","slug":"boss-2-魔导先锋强袭型","link":"#boss-2-魔导先锋强袭型","children":[]}]},{"level":2,"title":"BOSS 2 ~ BOSS 3","slug":"boss-2-boss-3","link":"#boss-2-boss-3","children":[{"level":3,"title":"BOSS 3 莉维亚·萨斯·尤尼乌斯","slug":"boss-3-莉维亚·萨斯·尤尼乌斯","link":"#boss-3-莉维亚·萨斯·尤尼乌斯","children":[]}]}],"relativePath":"duty/15.htm.md","filePath":"duty/15.md","lastUpdated":1791101830000}'),m={name:"duty/15.htm.md"};function p(O,s,b,k,B,_){const o=S("Role"),r=S("Status");return i(),d("div",null,[s[7]||(s[7]=n('<h1 id="神兵要塞帝国南方堡" tabindex="-1">神兵要塞帝国南方堡</h1><p>2.0 剧情收尾的重要剧情副本，部分动画不可跳过。</p><h2 id="进场-boss-1" tabindex="-1">进场～BOSS 1</h2><p>进门之后，一路向前撸，路上的警戒终端会在击杀全部敌人后自动打开。</p><h3 id="boss-1-魔导死神改" tabindex="-1">BOSS 1 魔导死神改</h3><p>会随机点名一人方向读条<mark>高功率魔导激光</mark>，没有范围提示，注意躲开 BOSS 正面。</p><p>召唤的小怪数量很多，T 注意拉住小怪仇恨，其他人注意使用范围攻击技能清理小怪。</p><h2 id="boss-1-boss-2" tabindex="-1">BOSS 1 ~ BOSS 2</h2><p>打完之后顺着动画的指示，从<mark>垃圾卸槽</mark>传送地图。读图后上楼，沿着右侧墙壁行进。看到两个<strong>魔导先锋</strong>的封锁处向左转，进入地图上的<mark>第五封锁区</mark>。</p><h3 id="boss-2-魔导先锋强袭型" tabindex="-1">BOSS 2 魔导先锋强袭型</h3><p>BOSS 读条<mark>请求投放气化炸弹</mark>后，场地上会出现一个圆形提示点，该技能为距离衰减型 AOE，需要远离提示落点，距离越远伤害越低。</p>',11)),e("p",null,[s[0]||(s[0]=t("其他技能出啥躲啥即可，注意",-1)),s[1]||(s[1]=e("mark",null,"陶瓷合金钻头",-1)),s[2]||(s[2]=t("是对 T 大伤害技能，",-1)),l(o,{name:"tank"}),s[3]||(s[3]=t("T 注意开好减伤。",-1))]),s[8]||(s[8]=n('<h2 id="boss-2-boss-3" tabindex="-1">BOSS 2 ~ BOSS 3</h2><p>打完 BOSS 后，从场地右侧岔路前进，打完刷出的 3 只小怪后继续向前，会有 NPC 帮忙把墙打烂。跟随 NPC 的魔导机甲继续前进。</p><h3 id="boss-3-莉维亚·萨斯·尤尼乌斯" tabindex="-1">BOSS 3 莉维亚・萨斯・尤尼乌斯</h3><p>开场<mark>魔导离子</mark>是全屏 AOE，<mark>典雅女神连枪</mark>是对 T 大伤害技能。接下来<mark>无尽旋风斩</mark>是先内后外的 AOE，先在外侧躲避中央的 AOE 圈，待中央的黄圈消失后，立刻前往中央躲避外侧的 AOE 伤害。</p><p>BOSS 读条<mark>无限刃</mark>后，是花里胡哨的 AOE 范围攻击，此时不可攻击 BOSS，只需要认真观察 AOE 范围，遵循先出现的先爆炸原则进行回避即可。如果实在找不到安全的落脚点，可以硬吃一个伤害，但万不可吃太多。</p><p>这个 BOSS 的<mark>请求投放气化炸弹</mark>是老二的加强版，需要先躲避一堆 AOE，再找落点。她的气化炸弹有 2 种模式：</p><ul><li>只有 2 个落点：场地边缘四分之一弧位置安全（与 2 个落点连线成等腰三角形顶点的位置）。</li><li>有 4 个落点：场地中央安全。</li></ul>',7)),e("p",null,[s[4]||(s[4]=t("最后 BOSS 使用",-1)),l(r,{id:1792,name:"魔导增幅器"}),s[5]||(s[5]=t("后，进入狂暴状态，会连续释放全屏 AOE。",-1)),l(o,{name:"healer"}),s[6]||(s[6]=t("治疗保证团队血线，其他人全力输出吧！",-1))])])}const A=a(m,[["render",p]]);export{T as __pageData,A as default};
